effect.shader:
void main() {
    if( acPass==0 ) {

        float angle = 0.0;
        float actualStrength = strength/4.0/iter;

        vec2 texelSize = 1.0 / vec2(inputImg.size);
        float rad = angle * 0.0174533;
        vec2 velocity = vec2(cos(rad)*actualStrength,-sin(rad)*actualStrength);
        float speed = length(velocity / texelSize);
        int nSamples = int(clamp(speed, 1.01, 100.01));
        vec4 outColor = texture2D(inputImg.texture,acScreenNorm.st);
        for(int i=1; i<nSamples; i++ ) {
            vec2 offset = velocity * (float(i) / float(nSamples - 1) - 0.5);
            outColor += texture2D(inputImg.texture, acScreenNorm.st-offset);
        }
        gl_FragColor = outColor/float(nSamples);

    } else {

        float angle = 90.0;
        float actualStrength = strength/4.0/iter;

        vec2 texelSize = 1.0 / vec2(inputImg.size);
        float rad = angle * 0.0174533;
        vec2 velocity = vec2(cos(rad)*actualStrength,-sin(rad)*actualStrength);
        float speed = length(velocity / texelSize);
        int nSamples = int(clamp(speed, 1.01, 100.01));
        vec4 baseColor = texture2D(inputImg.texture,acScreenNorm.st);
        vec4 outColor = texture2D(hblur.texture,acScreenNorm.st);
        for(int i=1; i<nSamples; i++ ) {
            vec2 offset = velocity * (float(i) / float(nSamples - 1) - 0.5);
            outColor += texture2D(hblur.texture, acScreenNorm.st-offset);
        }
        vec4 blurColor = outColor/float(nSamples);
        //vec4 compColor = baseColor * (1.-blurColor.a) + blurColor;
        vec4 compColor =  vec4(blurColor.rgb / blurColor.a, 1.);
        gl_FragColor = vec4(compColor.rgb / compColor.a,1.) * baseColor.a;

    }
}
